export function icon(name, { size = 18, stroke = 1.75, cls = "" } = {}) {
  const d = P[name] || P.info;
  return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" class="${cls}" aria-hidden="true"><path d="${d}"/></svg>`;
}

